"""WireGuard configuration (ZA-OPRAVYANE row 335; fixture L2/15-wireguard, keys from wg
genkey/pubkey/genpsk). On 0.41.0 the file read as "read every one", 0 evidence.

* https://www.wireguard.com/protocol/ -- "Curve25519 for ECDH"; "WireGuard also supports an
  optional pre-shared key that is mixed into the public key cryptography" "(for, say,
  post-quantum resistance)".
* wg(8), https://man7.org/linux/man-pages/man8/wg.8.html -- "There are two top level sections
  -- Interface and Peer"; "PrivateKey -- a base64 private key generated by wg genkey."
"""

from qrp_mcp.scan import scan_directory

WG = """[Interface]
PrivateKey = KKOCvXjFXJ/z1srID7IA8Pvii5voc97+QV/YfPa7LE0=
Address = 10.0.0.1/24

[Peer]
PublicKey = CGgIv+Ava2kpGUsLfu1UEbP7mMQSCYL5ByPvBWfAPws=
PresharedKey = qGR51FivkA9Y20T3rrJgsCDfFnV1a8U2Y4S9N41Mw9Y=
AllowedIPs = 10.0.0.2/32

[Peer]
PublicKey = CGgIv+Ava2kpGUsLfu1UEbP7mMQSCYL5ByPvBWfAPws=
AllowedIPs = 10.0.0.3/32
"""


def test_wireguard_key_exchange_and_private_key(tmp_path):
    (tmp_path / "wg0.conf").write_text(WG)
    result = scan_directory(tmp_path)
    rows = [(f["line"], f["algorithm"]) for f in result["evidence"]["source_code"]]
    assert rows == [(1, "X25519"), (5, "X25519"), (10, "X25519")]
    said = {f["line"]: f["description"] for f in result["evidence"]["source_code"]}
    assert "sets a PresharedKey" in said[5] and "no PresharedKey" in said[10]
    [key] = result["evidence"]["embedded_keys"]
    assert (key["line"], key["key_algorithm"]) == (2, "X25519")
    assert result["summary"]["pqc_readiness"] == "classical_only"


def test_an_ini_with_sections_is_not_wireguard(tmp_path):
    (tmp_path / "app.conf").write_text("[Interface]\nName = eth0\n[Peer]\nHost = a\n")
    result = scan_directory(tmp_path)
    assert result["evidence"]["source_code"] == []
